def exactitude(predictions, verites):
    justes = sum(1 for p, v in zip(predictions, verites) if p == v)
    return round(justes / len(verites), 2)

def matrice(predictions, verites, positif):
    m = {"vp": 0, "fp": 0, "fn": 0, "vn": 0}
    for p, v in zip(predictions, verites):
        if p == positif and v == positif:
            m["vp"] += 1
        elif p == positif:
            m["fp"] += 1
        elif v == positif:
            m["fn"] += 1
        else:
            m["vn"] += 1
    return m

def rappel(vp, fp, fn):
    if vp + fn == 0:
        return 0.0
    return round(vp / (vp + fn), 2)

def rapport(predictions, verites, positif):
    vp = sum(1 for p, v in zip(predictions, verites) if p == positif and v == positif)
    fp = sum(1 for p, v in zip(predictions, verites) if p == positif and v != positif)
    fn = sum(1 for p, v in zip(predictions, verites) if p != positif and v == positif)
    justes = sum(1 for p, v in zip(predictions, verites) if p == v)
    precision = vp / (vp + fp) if vp + fp else 0.0
    rappel = vp / (vp + fn) if vp + fn else 0.0
    return {"exactitude": round(justes / len(verites), 2), "precision": round(precision, 2), "rappel": round(rappel, 2)}
